#!/usr/bin/env node
// FYP.STUDIO — Dashboard compacto mobile + layout mobile completo
// node setup_mobile_compact.js (desde la raíz del proyecto)
const fs = require('fs'), path = require('path')
const files = {}

files["app/admin/AdminDashboardClient.tsx"] = "// app/admin/AdminDashboardClient.tsx\n'use client'\nimport { useState, useMemo } from 'react'\nimport {\n  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip,\n  ResponsiveContainer,\n} from 'recharts'\nimport {\n  TrendingUp, ShoppingBag, Users, Package,\n  ArrowUpRight, ArrowDownRight, ChevronDown, Zap,\n  CheckCircle2, Clock, XCircle,\n} from 'lucide-react'\nimport { formatPrice, orderStatusColor, orderStatusLabel } from '@/lib/utils'\nimport type { Order, Product } from '@/types'\n\ninterface Item { product_name: string; quantity: number; unit_price: number; order_id: string }\ninterface Props {\n  userName: string; orders: Order[]; products: Product[]\n  totalCustomers: number; allItems: Item[]\n  currency: string; primaryColor: string; businessName: string\n}\ntype Range = 'today' | 'yesterday' | '7d' | '30d' | 'month'\n\nconst RANGES: { key: Range; label: string }[] = [\n  { key: 'today',     label: 'Hoy'            },\n  { key: 'yesterday', label: 'Ayer'           },\n  { key: '7d',        label: 'Últimos 7 días' },\n  { key: '30d',       label: 'Últimos 30 días'},\n  { key: 'month',     label: 'Este mes'       },\n]\n\nconst BLUE = '#1565FF', DARK = '#0B3EAB', LIGHT = '#5FD1FF'\nconst GREEN = '#10B981', AMBER = '#F59E0B', RED = '#EF4444'\nconst BAR_COLORS = [BLUE, DARK, LIGHT, '#818CF8', '#6B7280']\n\nfunction rangeFilter(range: Range): (d: Date) => boolean {\n  const now = new Date()\n  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate())\n  switch (range) {\n    case 'today':     return d => d >= today\n    case 'yesterday': { const y = new Date(today); y.setDate(y.getDate()-1); return d => d>=y&&d<today }\n    case '7d':        { const s = new Date(today); s.setDate(s.getDate()-6); return d => d>=s }\n    case '30d':       { const s = new Date(today); s.setDate(s.getDate()-29); return d => d>=s }\n    case 'month':     return d => d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear()\n  }\n}\n\nfunction buildChartData(orders: Order[], range: Range) {\n  const now = new Date()\n  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate())\n  const pts: { label: string; ventas: number }[] = []\n  if (range === 'today' || range === 'yesterday') {\n    const base = new Date(today)\n    if (range === 'yesterday') base.setDate(base.getDate()-1)\n    for (let h = 0; h < 24; h += 2) {\n      const from = new Date(base); from.setHours(h)\n      const to   = new Date(base); to.setHours(h+2)\n      pts.push({\n        label: `${h}h`,\n        ventas: orders.filter(o=>o.confirmed_sale).filter(o=>{\n          const d=new Date(o.created_at); return d>=from&&d<to\n        }).reduce((a,o)=>a+o.total,0),\n      })\n    }\n  } else {\n    const days = range==='7d'?7:30\n    for (let i=days-1;i>=0;i--) {\n      const d=new Date(today); d.setDate(d.getDate()-i)\n      const next=new Date(d); next.setDate(next.getDate()+1)\n      pts.push({\n        label: d.toLocaleDateString('es-UY',{day:'numeric',month:'short'}),\n        ventas: orders.filter(o=>o.confirmed_sale).filter(o=>{\n          const od=new Date(o.created_at); return od>=d&&od<next\n        }).reduce((a,o)=>a+o.total,0),\n      })\n    }\n  }\n  return pts\n}\n\nfunction topProducts(items: Item[]) {\n  const map: Record<string,{qty:number;revenue:number}>={}\n  items.forEach(i=>{\n    if(!map[i.product_name])map[i.product_name]={qty:0,revenue:0}\n    map[i.product_name].qty+=i.quantity\n    map[i.product_name].revenue+=i.quantity*i.unit_price\n  })\n  return Object.entries(map).map(([name,v])=>({name,...v}))\n    .sort((a,b)=>b.revenue-a.revenue).slice(0,5)\n}\n\nfunction CustomTooltip({active,payload,label,currency}:{active?:boolean;payload?:{value:number}[];label?:string;currency:string}) {\n  if(!active||!payload?.length)return null\n  return(\n    <div className=\"rounded-xl bg-white border border-gray-100 shadow-lg px-3 py-2 text-xs\">\n      <p className=\"font-semibold text-gray-600 mb-0.5\">{label}</p>\n      <p style={{color:BLUE}}>{formatPrice(payload[0].value,currency)}</p>\n    </div>\n  )\n}\n\nfunction DonutMini({pct,color}:{pct:number;color:string}){\n  const r=14,circ=2*Math.PI*r,dash=Math.max(0,Math.min(pct/100,1))*circ\n  return(\n    <svg width=\"36\" height=\"36\" viewBox=\"0 0 36 36\">\n      <circle cx=\"18\" cy=\"18\" r={r} fill=\"none\" stroke=\"#EFF6FF\" strokeWidth=\"5\"/>\n      <circle cx=\"18\" cy=\"18\" r={r} fill=\"none\" stroke={color} strokeWidth=\"5\"\n        strokeDasharray={`${dash} ${circ}`} strokeDashoffset={circ/4}\n        strokeLinecap=\"round\" style={{transition:'stroke-dasharray .6s'}}/>\n    </svg>\n  )\n}\n\nexport default function AdminDashboardClient({\n  userName,orders,products,totalCustomers,allItems,currency,primaryColor,businessName\n}:Props){\n  const [range,setRange]=useState<Range>('7d')\n  const [dropOpen,setDropOpen]=useState(false)\n\n  const inRange=useMemo(()=>{\n    const fn=rangeFilter(range)\n    return orders.filter(o=>fn(new Date(o.created_at)))\n  },[orders,range])\n\n  const prevInRange=useMemo(()=>{\n    const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate())\n    const days=range==='today'||range==='yesterday'?1:range==='7d'?7:30\n    const from=new Date(today);from.setDate(from.getDate()-days*2)\n    const to=new Date(today);to.setDate(to.getDate()-days)\n    return orders.filter(o=>{const d=new Date(o.created_at);return d>=from&&d<to})\n  },[orders,range])\n\n  const revenue=inRange.filter(o=>o.confirmed_sale).reduce((a,o)=>a+o.total,0)\n  const prevRevenue=prevInRange.filter(o=>o.confirmed_sale).reduce((a,o)=>a+o.total,0)\n  const revDelta=prevRevenue>0?((revenue-prevRevenue)/prevRevenue)*100:null\n\n  const pendingCount=inRange.filter(o=>o.status==='pending').length\n  const confirmedCount=inRange.filter(o=>o.confirmed_sale).length\n  const cancelCount=inRange.filter(o=>o.status==='cancelled').length\n  const convRate=inRange.length>0?Math.round((confirmedCount/inRange.length)*100):0\n  const avgTicket=confirmedCount>0?revenue/confirmedCount:0\n\n  const chartData=useMemo(()=>buildChartData(orders,range),[orders,range])\n  const top=useMemo(()=>topProducts(allItems),[allItems])\n  const maxRev=top[0]?.revenue??1\n  const recentOrders=orders.slice(0,5)\n\n  const hour=new Date().getHours()\n  const greeting=hour<12?'Buenos días':hour<19?'Buenas tardes':'Buenas noches'\n  const emoji=hour<12?'☀️':hour<19?'👋':'🌙'\n  const rangeLabel=RANGES.find(r=>r.key===range)?.label??''\n\n  return(\n    <div className=\"space-y-4 animate-fade-in pb-4\">\n\n      {/* ── HEADER ── */}\n      <div className=\"flex items-start justify-between gap-3\">\n        <div>\n          <h1 className=\"text-lg lg:text-2xl font-bold text-gray-900 tracking-tight leading-tight\">\n            ¡{greeting}! {emoji}\n          </h1>\n          <p className=\"text-xs text-gray-400 mt-0.5\">{businessName}</p>\n        </div>\n\n        {/* Selector período */}\n        <div className=\"relative shrink-0\">\n          <button onClick={()=>setDropOpen(o=>!o)}\n            className=\"flex items-center gap-1.5 rounded-xl border border-gray-200 bg-white\n                       px-3 py-2 text-xs font-medium text-gray-700 shadow-sm\">\n            {rangeLabel}\n            <ChevronDown size={12} className={dropOpen?'rotate-180 transition-transform':'transition-transform'}/>\n          </button>\n          {dropOpen&&(\n            <>\n              <div className=\"fixed inset-0 z-10\" onClick={()=>setDropOpen(false)}/>\n              <div className=\"absolute right-0 top-10 z-20 w-44 rounded-2xl border border-gray-200\n                              bg-white py-1.5 shadow-xl\">\n                {RANGES.map(r=>(\n                  <button key={r.key} onClick={()=>{setRange(r.key);setDropOpen(false)}}\n                    className={`w-full flex items-center justify-between px-4 py-2 text-sm transition-colors\n                                ${range===r.key?'font-semibold text-blue-600 bg-blue-50':'text-gray-600 hover:bg-gray-50'}`}>\n                    {r.label}\n                    {range===r.key&&<div className=\"h-1.5 w-1.5 rounded-full bg-blue-500\"/>}\n                  </button>\n                ))}\n              </div>\n            </>\n          )}\n        </div>\n      </div>\n\n      {/* ── STAT CARDS — 2x2 en mobile, 4x1 en desktop ── */}\n      <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-3\">\n\n        {/* Ventas — hero */}\n        <div className=\"col-span-2 lg:col-span-1 rounded-2xl p-4 text-white relative overflow-hidden\"\n          style={{background:`linear-gradient(135deg,${BLUE},${DARK})`}}>\n          <div className=\"absolute -right-6 -top-6 h-24 w-24 rounded-full opacity-10 bg-white\"/>\n          <div className=\"relative\">\n            <div className=\"flex items-center justify-between mb-2\">\n              <p className=\"text-xs opacity-80\">Ventas · {rangeLabel}</p>\n              <TrendingUp size={14} className=\"opacity-70\"/>\n            </div>\n            <p className=\"text-2xl lg:text-3xl font-bold tracking-tight\">{formatPrice(revenue,currency)}</p>\n            {revDelta!==null?(\n              <div className=\"flex items-center gap-1 mt-1\">\n                {revDelta>=0?<ArrowUpRight size={11}/>:<ArrowDownRight size={11}/>}\n                <span className=\"text-[11px] opacity-80\">\n                  {revDelta>=0?'+':''}{revDelta.toFixed(1)}% vs anterior\n                </span>\n              </div>\n            ):<p className=\"text-[11px] opacity-50 mt-1\">Sin comparativa</p>}\n          </div>\n        </div>\n\n        {/* Órdenes */}\n        <MiniCard\n          label=\"Órdenes\" value={inRange.length}\n          sub={`${confirmedCount} confirmadas`}\n          icon={<ShoppingBag size={14}/>} iconBg=\"#DBEAFE\" iconColor={BLUE}\n        />\n\n        {/* Clientes */}\n        <MiniCard\n          label=\"Clientes\" value={totalCustomers}\n          sub={`${products.filter(p=>p.active).length} productos`}\n          icon={<Users size={14}/>} iconBg=\"#DCFCE7\" iconColor={GREEN}\n        />\n\n        {/* Facturado */}\n        <MiniCard\n          label=\"Ticket prom.\"\n          value={formatPrice(avgTicket,currency)}\n          sub={`Conv. ${convRate}%`}\n          icon={<TrendingUp size={14}/>} iconBg=\"#FEF3C7\" iconColor={AMBER}\n        />\n      </div>\n\n      {/* ── GRÁFICA ── */}\n      <div className=\"bg-white rounded-2xl border border-gray-100 p-4 shadow-sm\">\n        <div className=\"flex items-center justify-between mb-3\">\n          <p className=\"text-sm font-semibold text-gray-900\">Ventas</p>\n          <p className=\"text-sm font-bold text-gray-900\">{formatPrice(revenue,currency)}</p>\n        </div>\n        {chartData.every(p=>p.ventas===0)?(\n          <div className=\"h-24 flex items-center justify-center\">\n            <p className=\"text-xs text-gray-300\">Sin ventas confirmadas</p>\n          </div>\n        ):(\n          <ResponsiveContainer width=\"100%\" height={120}>\n            <AreaChart data={chartData} margin={{top:0,right:0,left:-35,bottom:0}}>\n              <defs>\n                <linearGradient id=\"gB\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                  <stop offset=\"0%\" stopColor={BLUE} stopOpacity={0.2}/>\n                  <stop offset=\"100%\" stopColor={BLUE} stopOpacity={0}/>\n                </linearGradient>\n              </defs>\n              <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#F3F4F6\" vertical={false}/>\n              <XAxis dataKey=\"label\" tick={{fontSize:9,fill:'#9CA3AF'}}\n                axisLine={false} tickLine={false}\n                interval={Math.floor(chartData.length/4)}/>\n              <YAxis tick={{fontSize:9,fill:'#9CA3AF'}} axisLine={false} tickLine={false}\n                tickFormatter={v=>v===0?'':'$'+Math.round(v/1000)+'k'}/>\n              <Tooltip content={<CustomTooltip currency={currency}/>}/>\n              <Area type=\"monotone\" dataKey=\"ventas\" stroke={BLUE} strokeWidth={2}\n                fill=\"url(#gB)\" dot={false} activeDot={{r:4,fill:BLUE}}/>\n            </AreaChart>\n          </ResponsiveContainer>\n        )}\n      </div>\n\n      {/* ── ESTADO PEDIDOS + TOP PRODUCTOS (en mobile: apilados) ── */}\n      <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-3\">\n\n        {/* Estado pedidos — 3 donuts compactos */}\n        <div className=\"bg-white rounded-2xl border border-gray-100 p-4 shadow-sm\">\n          <p className=\"text-sm font-semibold text-gray-900 mb-3\">Estado de pedidos</p>\n          <div className=\"grid grid-cols-3 gap-2\">\n            {[\n              {label:'Confirmados',value:confirmedCount,color:BLUE,   icon:<CheckCircle2 size={12}/>},\n              {label:'Pendientes', value:pendingCount,  color:AMBER,  icon:<Clock size={12}/>},\n              {label:'Cancelados', value:cancelCount,   color:RED,    icon:<XCircle size={12}/>},\n            ].map(({label,value,color,icon})=>(\n              <div key={label} className=\"flex flex-col items-center gap-1.5 py-2\">\n                <div className=\"relative\">\n                  <DonutMini pct={inRange.length>0?(value/inRange.length)*100:0} color={color}/>\n                  <div className=\"absolute inset-0 flex items-center justify-center\" style={{color}}>\n                    {icon}\n                  </div>\n                </div>\n                <p className=\"text-base font-bold text-gray-900\">{value}</p>\n                <p className=\"text-[10px] text-gray-400 text-center leading-tight\">{label}</p>\n              </div>\n            ))}\n          </div>\n          <div className=\"mt-3 pt-3 border-t border-gray-100 flex items-center justify-between\">\n            <div className=\"flex items-center gap-1.5\">\n              <Zap size={12} style={{color:BLUE}}/>\n              <p className=\"text-xs text-gray-600\">Conversión</p>\n            </div>\n            <p className=\"text-base font-bold\" style={{color:BLUE}}>{convRate}%</p>\n          </div>\n        </div>\n\n        {/* Top productos */}\n        <div className=\"bg-white rounded-2xl border border-gray-100 p-4 shadow-sm\">\n          <p className=\"text-sm font-semibold text-gray-900 mb-3\">Top productos</p>\n          {top.length===0?(\n            <div className=\"py-6 text-center\">\n              <Package size={20} className=\"mx-auto text-gray-200 mb-1\"/>\n              <p className=\"text-xs text-gray-400\">Sin ventas todavía</p>\n            </div>\n          ):(\n            <div className=\"space-y-3\">\n              {top.map((p,i)=>(\n                <div key={p.name} className=\"flex items-center gap-2\">\n                  <div className=\"h-5 w-5 rounded-lg flex items-center justify-center\n                                  text-[10px] font-bold text-white shrink-0\"\n                    style={{background:BAR_COLORS[i]??'#9CA3AF'}}>\n                    {i+1}\n                  </div>\n                  <div className=\"flex-1 min-w-0\">\n                    <div className=\"flex justify-between items-baseline mb-0.5\">\n                      <p className=\"text-xs font-medium text-gray-800 truncate pr-1\">{p.name}</p>\n                      <p className=\"text-xs font-bold text-gray-900 shrink-0\">\n                        {formatPrice(p.revenue,currency)}\n                      </p>\n                    </div>\n                    <div className=\"h-1 rounded-full overflow-hidden bg-gray-100\">\n                      <div className=\"h-full rounded-full transition-all duration-700\"\n                        style={{width:`${(p.revenue/maxRev)*100}%`,background:BAR_COLORS[i]??BLUE}}/>\n                    </div>\n                  </div>\n                </div>\n              ))}\n            </div>\n          )}\n        </div>\n      </div>\n\n      {/* ── PEDIDOS RECIENTES ── */}\n      <div className=\"bg-white rounded-2xl border border-gray-100 p-4 shadow-sm\">\n        <div className=\"flex items-center justify-between mb-3\">\n          <p className=\"text-sm font-semibold text-gray-900\">Pedidos recientes</p>\n          <a href=\"/admin/orders\" className=\"text-xs font-semibold\" style={{color:BLUE}}>\n            Ver todos →\n          </a>\n        </div>\n        {recentOrders.length===0?(\n          <div className=\"py-6 text-center\">\n            <ShoppingBag size={20} className=\"mx-auto text-gray-200 mb-1\"/>\n            <p className=\"text-xs text-gray-400\">Sin pedidos todavía</p>\n          </div>\n        ):(\n          <div className=\"space-y-0 divide-y divide-gray-50\">\n            {recentOrders.map(order=>(\n              <a key={order.id} href={`/admin/orders/${order.id}`}\n                className=\"flex items-center gap-3 py-2.5 hover:bg-gray-50/60 rounded-xl\n                           px-1 -mx-1 transition-colors\">\n                <div className=\"h-8 w-8 shrink-0 rounded-xl flex items-center justify-center\n                                text-xs font-bold text-white\"\n                  style={{background:`linear-gradient(135deg,${BLUE},${DARK})`}}>\n                  {order.customer_name.slice(0,1).toUpperCase()}\n                </div>\n                <div className=\"flex-1 min-w-0\">\n                  <p className=\"text-sm font-semibold text-gray-900 truncate\">{order.customer_name}</p>\n                  <p className=\"text-[11px] text-gray-400\">\n                    #{String(order.order_number).padStart(4,'0')}\n                  </p>\n                </div>\n                <div className=\"text-right shrink-0\">\n                  <p className=\"text-sm font-bold text-gray-900\">{formatPrice(order.total,currency)}</p>\n                  <span className={`badge text-[10px] ${orderStatusColor(order.status)}`}>\n                    {orderStatusLabel(order.status)}\n                  </span>\n                </div>\n              </a>\n            ))}\n          </div>\n        )}\n      </div>\n\n      {/* ── RESUMEN FINANCIERO ── */}\n      <div className=\"bg-white rounded-2xl border border-gray-100 overflow-hidden shadow-sm\">\n        <div className=\"px-4 py-3 border-b border-gray-100 bg-gray-50/50\">\n          <p className=\"text-xs font-semibold text-gray-600\">Resumen · {rangeLabel}</p>\n        </div>\n        <div className=\"grid grid-cols-2 divide-x divide-y divide-gray-100\">\n          {[\n            {label:'Ingresos',     value:formatPrice(revenue,currency),     color:'text-green-600'},\n            {label:'Pedidos',      value:inRange.length,                    color:'text-gray-900'},\n            {label:'Ticket prom.', value:formatPrice(avgTicket,currency),   color:'text-gray-900'},\n            {label:'Cancelaciones',value:cancelCount, color:cancelCount>0?'text-red-500':'text-gray-900'},\n          ].map(({label,value,color})=>(\n            <div key={label} className=\"p-4\">\n              <p className=\"text-[11px] text-gray-400 mb-0.5\">{label}</p>\n              <p className={`text-base font-bold ${color}`}>{value}</p>\n            </div>\n          ))}\n        </div>\n      </div>\n\n    </div>\n  )\n}\n\nfunction MiniCard({label,value,sub,icon,iconBg,iconColor}:{\n  label:string;value:string|number;sub:string\n  icon:React.ReactNode;iconBg:string;iconColor:string\n}){\n  return(\n    <div className=\"bg-white rounded-2xl border border-gray-100 p-4 shadow-sm\">\n      <div className=\"flex items-center justify-between mb-2\">\n        <div className=\"flex h-7 w-7 items-center justify-center rounded-lg\"\n          style={{background:iconBg,color:iconColor}}>\n          {icon}\n        </div>\n      </div>\n      <p className=\"text-xl font-bold text-gray-900 tracking-tight\">{value}</p>\n      <p className=\"text-[11px] text-gray-400 mt-0.5\">{label}</p>\n      <p className=\"text-[11px] font-medium mt-0.5\" style={{color:iconColor}}>{sub}</p>\n    </div>\n  )\n}\n"

files["components/admin/AdminShell.tsx"] = "// components/admin/AdminShell.tsx\n'use client'\nimport { useState, useEffect } from 'react'\nimport Link from 'next/link'\nimport { usePathname, useRouter } from 'next/navigation'\nimport { createClient } from '@/lib/supabase/client'\nimport {\n  LayoutDashboard, ShoppingBag, Package, Users, Settings,\n  Sparkles, LogOut, Tag, ExternalLink, Crown, Layers, Truck,\n  Menu, X, ChevronRight, MoreHorizontal,\n} from 'lucide-react'\nimport { cn } from '@/lib/utils'\nimport type { Business } from '@/types'\n\nconst NAV = [\n  { href: '/admin',            label: 'Inicio',        icon: LayoutDashboard, exact: true },\n  { href: '/admin/orders',     label: 'Pedidos',       icon: ShoppingBag },\n  { href: '/admin/products',   label: 'Productos',     icon: Package },\n  { href: '/admin/inventory',  label: 'Inventario',    icon: Layers },\n  { href: '/admin/suppliers',  label: 'Proveedores',   icon: Truck },\n  { href: '/admin/categories', label: 'Categorías',    icon: Tag },\n  { href: '/admin/customers',  label: 'Clientes',      icon: Users },\n  { href: '/admin/ai',         label: 'IA',            icon: Sparkles },\n  { href: '/admin/settings',   label: 'Configuración', icon: Settings },\n]\n\n// Bottom nav mobile — 4 principales + \"Más\"\nconst BOTTOM_MAIN = [\n  { href: '/admin',           label: 'Inicio',    icon: LayoutDashboard, exact: true },\n  { href: '/admin/orders',    label: 'Pedidos',   icon: ShoppingBag },\n  { href: '/admin/products',  label: 'Productos', icon: Package },\n  { href: '/admin/inventory', label: 'Stock',     icon: Layers },\n]\n\nfunction FypLogo({ size = 32 }: { size?: number }) {\n  return (\n    <svg width={size} height={size} viewBox=\"0 0 40 40\" fill=\"none\">\n      <rect width=\"40\" height=\"40\" rx=\"10\" fill=\"#1565FF\"/>\n      <path d=\"M10 10L10 30L14 30L14 22L22 22L22 18L14 18L14 14L24 14L24 10Z\" fill=\"white\" opacity=\"0.95\"/>\n      <path d=\"M20 14L20 26L24 26L24 22C27 22 30 20 30 18C30 16 27 14 24 14Z\" fill=\"white\" opacity=\"0.7\"/>\n    </svg>\n  )\n}\n\nfunction NavLink({\n  href, label, icon: Icon, exact, onClick,\n  style: linkStyle,\n}: {\n  href: string; label: string; icon: React.ElementType\n  exact?: boolean; onClick?: () => void; style?: React.CSSProperties\n}) {\n  const pathname = usePathname()\n  const isActive = exact ? pathname === href : pathname.startsWith(href)\n  return (\n    <Link href={href} onClick={onClick}\n      className={cn(\n        'flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-medium transition-all',\n        isActive ? 'text-white' : 'text-gray-400 hover:text-white hover:bg-white/5'\n      )}\n      style={isActive ? {\n        background: 'linear-gradient(90deg,rgba(21,101,255,0.22),rgba(21,101,255,0.08))',\n        borderLeft: '3px solid #1565FF',\n        paddingLeft: '9px',\n        ...linkStyle,\n      } : linkStyle}\n    >\n      <Icon size={15} className={isActive ? 'text-blue-400' : ''} />\n      <span className=\"flex-1\">{label}</span>\n      {isActive && <ChevronRight size={12} className=\"text-blue-400/60\" />}\n    </Link>\n  )\n}\n\n// ── Sidebar (desktop) ─────────────────────────────────────────\nfunction Sidebar({ business, userEmail }: { business: Business | null; userEmail: string }) {\n  const router = useRouter()\n  const supabase = createClient()\n\n  async function handleLogout() {\n    await supabase.auth.signOut()\n    router.push('/auth/login')\n    router.refresh()\n  }\n\n  return (\n    <aside\n      className=\"hidden lg:flex w-[220px] flex-col h-full shrink-0\"\n      style={{ background: '#0B1929', borderRight: '1px solid rgba(255,255,255,0.06)' }}\n    >\n      {/* Logo */}\n      <div className=\"px-5 py-5 border-b\" style={{ borderColor: 'rgba(255,255,255,0.06)' }}>\n        <div className=\"flex items-center gap-3\">\n          <FypLogo size={34} />\n          <div>\n            <p className=\"text-white font-bold text-sm tracking-tight\">FyP Studio</p>\n            <p className=\"text-[11px] mt-0.5 truncate max-w-[120px]\" style={{ color: '#5FD1FF' }}>\n              {business?.name ?? 'Panel admin'}\n            </p>\n          </div>\n        </div>\n      </div>\n\n      {/* Nav */}\n      <nav className=\"flex-1 px-3 pt-3 space-y-0.5 overflow-y-auto\">\n        {NAV.map(item => <NavLink key={item.href} {...item} />)}\n      </nav>\n\n      {/* Plan badge */}\n      {(business?.plan === 'pro' || business?.plan === 'premium') && (\n        <div className=\"mx-3 mb-3 rounded-xl p-3\"\n          style={{ background: 'linear-gradient(135deg,#1565FF22,#0B3EAB15)', border: '1px solid #1565FF33' }}>\n          <div className=\"flex items-center gap-2 mb-0.5\">\n            <Crown size={12} className=\"text-yellow-400\" />\n            <span className=\"text-xs font-bold text-white capitalize\">{business.plan}</span>\n          </div>\n          <p className=\"text-[10px] text-gray-400\">Más funciones activas</p>\n        </div>\n      )}\n\n      {/* Footer */}\n      <div className=\"px-3 pb-4 pt-3 border-t space-y-0.5\"\n        style={{ borderColor: 'rgba(255,255,255,0.06)' }}>\n        {business?.slug && (\n          <Link href={`/store/${business.slug}`} target=\"_blank\"\n            className=\"flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-gray-400\n                       hover:text-white hover:bg-white/5 transition-all\">\n            <ExternalLink size={14} /> Ver tienda\n          </Link>\n        )}\n        <button onClick={handleLogout}\n          className=\"w-full flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-gray-400\n                     hover:text-red-400 hover:bg-red-500/10 transition-all\">\n          <LogOut size={14} /> Salir\n        </button>\n        <p className=\"px-3 pt-1 text-[10px] truncate\" style={{ color: '#374151' }}>{userEmail}</p>\n      </div>\n    </aside>\n  )\n}\n\n// ── Drawer mobile (overlay) ───────────────────────────────────\nfunction MobileDrawer({\n  open, onClose, business, userEmail,\n}: {\n  open: boolean; onClose: () => void\n  business: Business | null; userEmail: string\n}) {\n  const router = useRouter()\n  const supabase = createClient()\n\n  // Cerrar con Escape\n  useEffect(() => {\n    const fn = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose() }\n    document.addEventListener('keydown', fn)\n    return () => document.removeEventListener('keydown', fn)\n  }, [onClose])\n\n  // Bloquear scroll body\n  useEffect(() => {\n    if (open) document.body.style.overflow = 'hidden'\n    else document.body.style.overflow = ''\n    return () => { document.body.style.overflow = '' }\n  }, [open])\n\n  async function handleLogout() {\n    await supabase.auth.signOut()\n    router.push('/auth/login')\n    router.refresh()\n  }\n\n  return (\n    <>\n      {/* Overlay */}\n      <div\n        onClick={onClose}\n        className={cn(\n          'fixed inset-0 z-40 bg-black/60 backdrop-blur-sm transition-opacity duration-300 lg:hidden',\n          open ? 'opacity-100' : 'opacity-0 pointer-events-none'\n        )}\n      />\n\n      {/* Drawer */}\n      <div\n        className={cn(\n          'fixed top-0 left-0 bottom-0 z-50 w-72 flex flex-col transition-transform duration-300 ease-out lg:hidden',\n        )}\n        style={{\n          background: '#0B1929',\n          transform: open ? 'translateX(0)' : 'translateX(-100%)',\n          boxShadow: open ? '4px 0 32px rgba(0,0,0,0.4)' : 'none',\n        }}\n      >\n        {/* Header drawer */}\n        <div className=\"flex items-center justify-between px-5 py-4 border-b\"\n          style={{ borderColor: 'rgba(255,255,255,0.08)' }}>\n          <div className=\"flex items-center gap-3\">\n            <FypLogo size={32} />\n            <div>\n              <p className=\"text-white font-bold text-sm\">FyP Studio</p>\n              <p className=\"text-[10px]\" style={{ color: '#5FD1FF' }}>\n                {business?.name ?? 'Panel'}\n              </p>\n            </div>\n          </div>\n          <button onClick={onClose}\n            className=\"flex h-8 w-8 items-center justify-center rounded-xl text-gray-400\n                       hover:bg-white/10 hover:text-white transition-all\">\n            <X size={18} />\n          </button>\n        </div>\n\n        {/* Nav drawer */}\n        <nav className=\"flex-1 px-3 pt-4 space-y-0.5 overflow-y-auto pb-4\">\n          {NAV.map(item => (\n            <NavLink key={item.href} {...item} onClick={onClose} />\n          ))}\n        </nav>\n\n        {/* Plan badge */}\n        {(business?.plan === 'pro' || business?.plan === 'premium') && (\n          <div className=\"mx-3 mb-3 rounded-xl p-3\"\n            style={{ background: '#1565FF18', border: '1px solid #1565FF33' }}>\n            <div className=\"flex items-center gap-2 mb-0.5\">\n              <Crown size={12} className=\"text-yellow-400\" />\n              <span className=\"text-xs font-bold text-white capitalize\">{business.plan}</span>\n            </div>\n            <p className=\"text-[10px] text-gray-400\">Más funciones activas</p>\n          </div>\n        )}\n\n        {/* Footer drawer */}\n        <div className=\"px-3 pb-6 pt-3 border-t space-y-0.5\"\n          style={{ borderColor: 'rgba(255,255,255,0.06)' }}>\n          {business?.slug && (\n            <Link href={`/store/${business.slug}`} target=\"_blank\" onClick={onClose}\n              className=\"flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-gray-400\n                         hover:text-white hover:bg-white/5 transition-all\">\n              <ExternalLink size={14} /> Ver tienda\n            </Link>\n          )}\n          <button onClick={handleLogout}\n            className=\"w-full flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-gray-400\n                       hover:text-red-400 hover:bg-red-500/10 transition-all\">\n            <LogOut size={14} /> Cerrar sesión\n          </button>\n          <p className=\"px-3 pt-2 text-[10px] truncate\" style={{ color: '#374151' }}>{userEmail}</p>\n        </div>\n      </div>\n    </>\n  )\n}\n\n// ── Top bar mobile ────────────────────────────────────────────\nfunction MobileTopBar({\n  business, userEmail, onMenuOpen,\n}: {\n  business: Business | null; userEmail: string; onMenuOpen: () => void\n}) {\n  const pathname = usePathname()\n\n  // Título de la página actual\n  const currentNav = NAV.find(n =>\n    n.exact ? pathname === n.href : (pathname.startsWith(n.href) && n.href !== '/admin')\n  ) ?? NAV[0]\n\n  return (\n    <header\n      className=\"lg:hidden h-14 shrink-0 flex items-center justify-between px-4 border-b\"\n      style={{ background: '#0B1929', borderColor: 'rgba(255,255,255,0.08)' }}\n    >\n      {/* Hamburger */}\n      <button\n        onClick={onMenuOpen}\n        className=\"flex h-9 w-9 items-center justify-center rounded-xl text-gray-400\n                   hover:bg-white/10 hover:text-white transition-all\"\n      >\n        <Menu size={20} />\n      </button>\n\n      {/* Logo centro */}\n      <div className=\"flex items-center gap-2\">\n        <FypLogo size={26} />\n        <span className=\"text-white font-bold text-sm\">FyP Studio</span>\n      </div>\n\n      {/* Avatar */}\n      <div\n        className=\"h-8 w-8 rounded-full flex items-center justify-center text-white text-xs font-bold\"\n        style={{ background: 'linear-gradient(135deg, #1565FF, #0B3EAB)' }}\n      >\n        {userEmail.slice(0, 1).toUpperCase()}\n      </div>\n    </header>\n  )\n}\n\n// ── Bottom nav mobile ─────────────────────────────────────────\nfunction BottomNav({ onMoreOpen }: { onMoreOpen: () => void }) {\n  const pathname = usePathname()\n\n  return (\n    <nav\n      className=\"lg:hidden fixed bottom-0 left-0 right-0 z-30 flex items-center\n                 border-t safe-area-bottom\"\n      style={{\n        background: '#0B1929',\n        borderColor: 'rgba(255,255,255,0.08)',\n        paddingBottom: 'env(safe-area-inset-bottom)',\n      }}\n    >\n      {BOTTOM_MAIN.map(({ href, label, icon: Icon, exact }) => {\n        const isActive = exact ? pathname === href : pathname.startsWith(href)\n        return (\n          <Link key={href} href={href}\n            className=\"flex-1 flex flex-col items-center gap-1 py-3 transition-all\"\n          >\n            <div className={cn(\n              'flex items-center justify-center h-7 w-7 rounded-xl transition-all',\n              isActive ? 'bg-blue-500/20' : ''\n            )}>\n              <Icon size={18} className={isActive ? 'text-blue-400' : 'text-gray-500'} />\n            </div>\n            <span className={cn(\n              'text-[10px] font-medium',\n              isActive ? 'text-blue-400' : 'text-gray-500'\n            )}>\n              {label}\n            </span>\n          </Link>\n        )\n      })}\n\n      {/* Más → abre drawer */}\n      <button\n        onClick={onMoreOpen}\n        className=\"flex-1 flex flex-col items-center gap-1 py-3\"\n      >\n        <div className=\"flex items-center justify-center h-7 w-7 rounded-xl\">\n          <MoreHorizontal size={18} className=\"text-gray-500\" />\n        </div>\n        <span className=\"text-[10px] font-medium text-gray-500\">Más</span>\n      </button>\n    </nav>\n  )\n}\n\n// ── Top bar desktop ───────────────────────────────────────────\nfunction DesktopTopBar({ userEmail }: { userEmail: string }) {\n  return (\n    <header className=\"hidden lg:flex h-14 shrink-0 items-center justify-between px-6\n                       bg-white border-b border-gray-100\">\n      <div className=\"flex-1\" />\n      <div\n        className=\"h-8 w-8 rounded-full flex items-center justify-center text-white text-xs font-bold\"\n        style={{ background: 'linear-gradient(135deg, #1565FF, #0B3EAB)' }}\n      >\n        {userEmail.slice(0, 1).toUpperCase()}\n      </div>\n    </header>\n  )\n}\n\n// ── SHELL PRINCIPAL ───────────────────────────────────────────\nexport default function AdminShell({\n  children, business, userEmail, suspended,\n}: {\n  children: React.ReactNode\n  business: Business | null\n  userEmail: string\n  suspended: boolean\n}) {\n  const [drawerOpen, setDrawerOpen] = useState(false)\n\n  return (\n    <div className=\"flex h-screen overflow-hidden\" style={{ background: '#F7F9FC' }}>\n\n      {/* ── Desktop sidebar ── */}\n      <Sidebar business={business} userEmail={userEmail} />\n\n      {/* ── Mobile drawer ── */}\n      <MobileDrawer\n        open={drawerOpen}\n        onClose={() => setDrawerOpen(false)}\n        business={business}\n        userEmail={userEmail}\n      />\n\n      {/* ── Contenido principal ── */}\n      <div className=\"flex-1 flex flex-col overflow-hidden min-w-0\">\n\n        {/* Top bars */}\n        <MobileTopBar\n          business={business}\n          userEmail={userEmail}\n          onMenuOpen={() => setDrawerOpen(true)}\n        />\n        <DesktopTopBar userEmail={userEmail} />\n\n        {/* Banner suscripción */}\n        {suspended && (\n          <div className=\"bg-red-500 text-white text-xs text-center py-2 px-4 font-medium shrink-0\">\n            ⚠️ Suscripción suspendida — contactá soporte para reactivar\n          </div>\n        )}\n\n        {/* Main content */}\n        <main className=\"flex-1 overflow-y-auto\">\n          {/* Padding bottom en mobile para no quedar debajo del bottom nav */}\n          <div className=\"p-4 lg:p-8 pb-24 lg:pb-8 max-w-6xl mx-auto\">\n            {children}\n          </div>\n        </main>\n\n        {/* Bottom nav mobile */}\n        <BottomNav onMoreOpen={() => setDrawerOpen(true)} />\n      </div>\n    </div>\n  )\n}\n"

files["app/admin/layout.tsx"] = "// app/admin/layout.tsx\nimport { redirect } from 'next/navigation'\nimport { createClient } from '@/lib/supabase/server'\nimport AdminShell from '@/components/admin/AdminShell'\n\nexport default async function AdminLayout({ children }: { children: React.ReactNode }) {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('*, business:businesses(*)')\n    .eq('user_id', user.id)\n    .single()\n\n  const needsOnboarding = !profile || !profile.business_id\n  const business = profile?.business ?? null\n\n  if (needsOnboarding) {\n    return (\n      <div style={{ background: '#F7F9FC', minHeight: '100vh' }}>\n        {children}\n      </div>\n    )\n  }\n\n  return (\n    <AdminShell\n      business={business}\n      userEmail={user.email ?? ''}\n      suspended={business?.subscription_status === 'suspended'}\n    >\n      {children}\n    </AdminShell>\n  )\n}\n"

files["app/admin/orders/page.tsx"] = "// app/admin/orders/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport { formatPrice, formatDate, orderStatusLabel, orderStatusColor } from '@/lib/utils'\nimport Link from 'next/link'\nimport { ShoppingBag, ChevronRight } from 'lucide-react'\nimport OrderStatusFilter from './OrderStatusFilter'\nimport type { Order } from '@/types'\n\nexport const metadata = { title: 'Pedidos' }\n\nconst ALL_STATUSES = ['pending','confirmed','preparing','ready','shipped','delivered','cancelled']\n\nexport default async function OrdersPage({ searchParams }: { searchParams: { status?: string } }) {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id, business:businesses(currency)')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const currency = (profile.business as { currency?: string } | null)?.currency ?? 'UYU'\n  const statusFilter = searchParams.status && ALL_STATUSES.includes(searchParams.status)\n    ? searchParams.status : null\n\n  let query = supabase\n    .from('orders')\n    .select('*, items:order_items(product_name, quantity, unit_price)')\n    .eq('business_id', profile.business_id)\n    .order('created_at', { ascending: false })\n\n  if (statusFilter) query = query.eq('status', statusFilter)\n\n  const { data: orders } = await query\n  const list = (orders ?? []) as Order[]\n\n  const counts: Record<string, number> = {}\n  ALL_STATUSES.forEach(s => { counts[s] = list.filter(o => o.status === s).length })\n\n  return (\n    <div className=\"space-y-5 animate-fade-in\">\n      <div className=\"flex items-center justify-between\">\n        <div>\n          <h1 className=\"text-xl lg:text-2xl font-bold text-gray-900 tracking-tight\">Pedidos</h1>\n          <p className=\"text-sm text-gray-400 mt-0.5\">{list.length} resultados</p>\n        </div>\n      </div>\n\n      <OrderStatusFilter current={statusFilter} counts={counts} />\n\n      {list.length === 0 ? (\n        <div className=\"rounded-2xl border-2 border-dashed border-gray-200 py-16 text-center\">\n          <ShoppingBag size={28} className=\"mx-auto text-gray-200 mb-3\" />\n          <p className=\"text-sm font-medium text-gray-400\">\n            {statusFilter ? `Sin pedidos con este estado` : 'Sin pedidos todavía'}\n          </p>\n        </div>\n      ) : (\n        <div className=\"space-y-2\">\n          {list.map(order => (\n            <Link key={order.id} href={`/admin/orders/${order.id}`}\n              className=\"block bg-white rounded-2xl border border-gray-100\n                         hover:border-gray-300 hover:shadow-sm transition-all active:scale-[0.99]\">\n              <div className=\"flex items-center gap-3 px-4 py-4\">\n                {/* Estado dot */}\n                <div className=\"shrink-0 flex flex-col items-center gap-1\">\n                  <p className=\"text-xs font-mono text-gray-400\">\n                    #{String(order.order_number).padStart(4,'0')}\n                  </p>\n                  <span className={`badge text-[10px] ${orderStatusColor(order.status)}`}>\n                    {orderStatusLabel(order.status)}\n                  </span>\n                </div>\n\n                {/* Info cliente */}\n                <div className=\"flex-1 min-w-0\">\n                  <p className=\"text-sm font-semibold text-gray-900 truncate\">{order.customer_name}</p>\n                  <p className=\"text-xs text-gray-400 mt-0.5 truncate\">\n                    {order.customer_phone ?? '—'} ·{' '}\n                    {order.delivery_type === 'delivery' ? '🛵 Delivery' : '🏃 Retiro'}\n                  </p>\n                  {/* Items — visible en mobile */}\n                  {order.items && order.items.length > 0 && (\n                    <p className=\"text-xs text-gray-400 mt-1 truncate hidden sm:block\">\n                      {order.items.map(i => `${i.quantity}x ${i.product_name}`).join(' · ')}\n                    </p>\n                  )}\n                </div>\n\n                {/* Total + fecha + flecha */}\n                <div className=\"shrink-0 text-right\">\n                  <p className=\"text-sm font-bold text-gray-900\">\n                    {formatPrice(order.total, currency)}\n                  </p>\n                  <p className=\"text-xs text-gray-400 mt-0.5\">\n                    {new Date(order.created_at).toLocaleDateString('es-UY',{\n                      day:'numeric', month:'short'\n                    })}\n                  </p>\n                </div>\n                <ChevronRight size={14} className=\"text-gray-300 shrink-0\" />\n              </div>\n            </Link>\n          ))}\n        </div>\n      )}\n    </div>\n  )\n}\n"

files["app/admin/products/page.tsx"] = "// app/admin/products/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport { formatPrice } from '@/lib/utils'\nimport Link from 'next/link'\nimport { Plus, Package } from 'lucide-react'\nimport ProductActions from './ProductActions'\nimport type { Product } from '@/types'\n\nexport const metadata = { title: 'Productos' }\n\nexport default async function ProductsPage() {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id, business:businesses(currency)')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const { data: products } = await supabase\n    .from('products')\n    .select('*, category:categories(name)')\n    .eq('business_id', profile.business_id)\n    .order('created_at', { ascending: false })\n\n  const currency = (profile.business as { currency?: string } | null)?.currency ?? 'UYU'\n  const list = (products ?? []) as (Product & { category?: { name: string } | null })[]\n  const active = list.filter(p => p.active).length\n\n  return (\n    <div className=\"space-y-5 animate-fade-in\">\n      <div className=\"flex items-center justify-between\">\n        <div>\n          <h1 className=\"text-xl lg:text-2xl font-bold text-gray-900 tracking-tight\">Productos</h1>\n          <p className=\"text-sm text-gray-400 mt-0.5\">{active} activos · {list.length - active} inactivos</p>\n        </div>\n        <Link href=\"/admin/products/new\"\n          className=\"flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold\n                     text-white active:scale-[0.98] transition-all\"\n          style={{ background: '#1565FF' }}>\n          <Plus size={15} />\n          <span className=\"hidden sm:inline\">Nuevo producto</span>\n          <span className=\"sm:hidden\">Nuevo</span>\n        </Link>\n      </div>\n\n      {list.length === 0 ? (\n        <div className=\"rounded-2xl border-2 border-dashed border-gray-200 py-16 text-center\">\n          <Package size={32} className=\"mx-auto text-gray-200 mb-3\" />\n          <p className=\"text-sm font-medium text-gray-400\">Sin productos todavía</p>\n          <p className=\"text-xs text-gray-300 mt-1 mb-5\">Creá tu primer producto para empezar</p>\n          <Link href=\"/admin/products/new\"\n            className=\"inline-flex items-center gap-2 rounded-xl px-5 py-2.5 text-sm font-semibold text-white\"\n            style={{ background: '#1565FF' }}>\n            <Plus size={14} /> Crear producto\n          </Link>\n        </div>\n      ) : (\n        <div className=\"space-y-2\">\n          {list.map(product => (\n            <div key={product.id}\n              className=\"flex items-center gap-3 bg-white rounded-2xl border border-gray-100\n                         px-4 py-3.5 hover:border-gray-200 transition-all\">\n              {/* Imagen */}\n              <div className=\"h-12 w-12 rounded-xl overflow-hidden bg-gray-100 shrink-0\">\n                {product.images?.[0] ? (\n                  <img src={product.images[0]} alt={product.name}\n                    className=\"h-full w-full object-cover\" />\n                ) : (\n                  <div className=\"h-full w-full flex items-center justify-center\">\n                    <Package size={16} className=\"text-gray-300\" />\n                  </div>\n                )}\n              </div>\n\n              {/* Info */}\n              <div className=\"flex-1 min-w-0\">\n                <div className=\"flex items-center gap-2\">\n                  <p className=\"text-sm font-semibold text-gray-900 truncate\">{product.name}</p>\n                  {product.featured && (\n                    <span className=\"text-[10px] text-amber-500 font-bold shrink-0\">★</span>\n                  )}\n                </div>\n                <div className=\"flex items-center gap-2 mt-0.5 flex-wrap\">\n                  <p className=\"text-sm font-bold\" style={{ color: '#1565FF' }}>\n                    {formatPrice(product.price, currency)}\n                  </p>\n                  {product.category?.name && (\n                    <span className=\"text-xs text-gray-400 hidden sm:inline\">\n                      · {product.category.name}\n                    </span>\n                  )}\n                  <span className={`badge text-[10px] ${\n                    product.active ? 'bg-green-50 text-green-700' : 'bg-gray-100 text-gray-400'\n                  }`}>\n                    {product.active ? 'Activo' : 'Inactivo'}\n                  </span>\n                </div>\n                {product.stock !== null && product.stock !== undefined && (\n                  <p className={`text-xs mt-0.5 ${\n                    product.stock === 0 ? 'text-red-500' :\n                    product.stock <= 5 ? 'text-amber-500' : 'text-gray-400'\n                  }`}>\n                    Stock: {product.stock} unidades\n                  </p>\n                )}\n              </div>\n\n              {/* Acciones */}\n              <ProductActions productId={product.id} isActive={product.active} />\n            </div>\n          ))}\n        </div>\n      )}\n    </div>\n  )\n}\n"

files["app/admin/customers/page.tsx"] = "// app/admin/customers/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport { formatPrice } from '@/lib/utils'\nimport { Users, Phone, ShoppingBag, TrendingUp } from 'lucide-react'\nimport type { Customer } from '@/types'\n\nexport const metadata = { title: 'Clientes' }\n\nexport default async function CustomersPage() {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id, business:businesses(currency)')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const currency = (profile.business as { currency?: string } | null)?.currency ?? 'UYU'\n\n  const { data: customers } = await supabase\n    .from('customers')\n    .select('*')\n    .eq('business_id', profile.business_id)\n    .order('total_orders', { ascending: false })\n\n  const list = (customers ?? []) as Customer[]\n  const totalRevenue = list.reduce((a, c) => a + (c.total_spent ?? 0), 0)\n  const totalOrders  = list.reduce((a, c) => a + (c.total_orders ?? 0), 0)\n\n  return (\n    <div className=\"space-y-5 animate-fade-in\">\n      <div>\n        <h1 className=\"text-xl lg:text-2xl font-bold text-gray-900 tracking-tight\">Clientes</h1>\n        <p className=\"text-sm text-gray-400 mt-0.5\">{list.length} registrados</p>\n      </div>\n\n      {/* Stats */}\n      {list.length > 0 && (\n        <div className=\"grid grid-cols-3 gap-3\">\n          {[\n            { label: 'Clientes',         value: list.length,                    icon: Users      },\n            { label: 'Pedidos',          value: totalOrders,                    icon: ShoppingBag},\n            { label: 'Facturación',      value: formatPrice(totalRevenue, currency), icon: TrendingUp },\n          ].map(({ label, value, icon: Icon }) => (\n            <div key={label} className=\"bg-white rounded-2xl border border-gray-100 p-4 shadow-sm text-center\">\n              <Icon size={16} className=\"mx-auto text-gray-400 mb-2\" />\n              <p className=\"text-lg font-bold text-gray-900\">{value}</p>\n              <p className=\"text-xs text-gray-400 mt-0.5\">{label}</p>\n            </div>\n          ))}\n        </div>\n      )}\n\n      {list.length === 0 ? (\n        <div className=\"rounded-2xl border-2 border-dashed border-gray-200 py-16 text-center\">\n          <Users size={28} className=\"mx-auto text-gray-200 mb-3\" />\n          <p className=\"text-sm font-medium text-gray-400\">Sin clientes todavía</p>\n          <p className=\"text-xs text-gray-300 mt-1\">\n            Los clientes se registran automáticamente al hacer pedidos\n          </p>\n        </div>\n      ) : (\n        /* Cards en lugar de tabla — mejor en mobile */\n        <div className=\"space-y-2\">\n          {list.map(customer => (\n            <div key={customer.id}\n              className=\"flex items-center gap-3 bg-white rounded-2xl border border-gray-100 px-4 py-3.5\">\n              {/* Avatar */}\n              <div className=\"h-10 w-10 rounded-full bg-gradient-to-br from-blue-500 to-blue-700\n                              flex items-center justify-center text-white text-sm font-bold shrink-0\">\n                {customer.name.slice(0, 1).toUpperCase()}\n              </div>\n\n              {/* Info */}\n              <div className=\"flex-1 min-w-0\">\n                <p className=\"text-sm font-semibold text-gray-900 truncate\">{customer.name}</p>\n                {customer.phone && (\n                  <a href={`https://wa.me/${customer.phone.replace(/\\D/g,'')}`}\n                    target=\"_blank\"\n                    className=\"flex items-center gap-1 text-xs text-green-600 mt-0.5 w-fit\">\n                    <Phone size={11} /> {customer.phone}\n                  </a>\n                )}\n                {customer.address && (\n                  <p className=\"text-xs text-gray-400 truncate mt-0.5 hidden sm:block\">\n                    {customer.address}\n                  </p>\n                )}\n              </div>\n\n              {/* Stats */}\n              <div className=\"text-right shrink-0\">\n                <p className=\"text-sm font-bold text-gray-900\">\n                  {formatPrice(customer.total_spent ?? 0, currency)}\n                </p>\n                <p className=\"text-xs text-gray-400 mt-0.5\">\n                  {customer.total_orders} {customer.total_orders === 1 ? 'pedido' : 'pedidos'}\n                </p>\n              </div>\n            </div>\n          ))}\n        </div>\n      )}\n    </div>\n  )\n}\n"

for (const [p,c] of Object.entries(files)) {
  const d = path.dirname(p)
  if (!fs.existsSync(d)) fs.mkdirSync(d,{recursive:true})
  fs.writeFileSync(p,c,'utf8')
  console.log('  ✅ '+p)
}
